int fac(int x){
    int now=x/2000000,res=jie[now];
    for(int i=now*2000000+1;i<=x;i++) res=1ll*res*i%mod;
    return res;
}
map<int,int>val,pre,tag,vis;
vector<int>p;
void add(ll &u,ll v){u=(u+v)%mod;}
ll dp[4],f[4];
struct MAT{
    ll a[4][4];
    MAT(){memset(a,0,sizeof(a));}
    MAT operator*(const MAT &rs)const{
        MAT res;
        for(int i=0;i<4;i++) for(int j=0;j<4;j++) for(int k=0;k<4;k++) res.a[i][j]=(res.a[i][j]+1ll*a[i][k]*rs.a[k][j])%mod;
        return res;
    }
};
MAT ksm(MAT u,int v){
    v--;
    MAT t=u;
    while(v){
        if(v&1) t=t*u;
        u=u*u,v>>=1;
    }
    return t;
}
void solve(){
    cin>>n>>m;
    int flag=1;
    val.clear(),pre.clear(),tag.clear(),vis.clear();
    int cnt=0;
    for(int i=1,x,y;i<=m;i++){
        cin>>x>>y;
        if((val.count(x)||vis.count(y))&&val[x]!=y){flag=-1;continue;}
        if(val[x]) continue;
        val[x]=y,vis[y]=1,cnt++;
        val[x]=y;
        if(flag!=1) continue;
        if(y>x+2){flag=0;continue;}
        if(y==x+2) continue;
        if(y==x+1) tag[y-2]|=4;
        else{
            tag[y-1]|=2,tag[y-2]|=4;
            if(y<x) tag[y]|=1,pre[y+1]++,pre[x]--;
        }
    }
    if(flag==-1){cout<<"0\n";return;}
    tag[n]|=2,tag[n-1]|=4;
    for(auto [i,v]:val){
        if(v==i+2&&(tag[i]&4)){flag=0;break;}
        if(v==i+1&&(tag[i]&2)){flag=0;break;}
    }
    if(!flag){cout<<fac(n-cnt)<<"\n";return;}
    p.clear();
    for(auto [i,j]:val) if(i>0) p.emplace_back(i),p.emplace_back(i+1);
    for(auto [i,j]:pre) if(i>0) p.emplace_back(i);
    for(auto [i,j]:tag) if(i>0) p.emplace_back(i),p.emplace_back(i+1);
    p.emplace_back(1),p.emplace_back(n+1);
    sort(p.begin(),p.end());int pn=unique(p.begin(),p.end())-p.begin();
    dp[0]=1,dp[1]=dp[2]=dp[3]=0;
    int sum=0;
    for(int ii=0;ii<pn-1;ii++){
        f[0]=f[1]=f[2]=f[3]=0;
        int i=p[ii];
        sum+=pre[i];
        if(sum>2){cout<<fac(n-cnt)<<"\n";return;}
        if(val[i]){
            if(val[i]==i+2) add(f[1],dp[0]+dp[2]);
            if(val[i]==i+1) add(f[2],dp[0]+dp[2]);
            if(val[i]==i) add(f[0],dp[0]);
            if(val[i]<i) add(f[0],dp[0]+dp[2]),add(f[2],dp[1]+dp[3]);
        }
        else{
            MAT base;
            if(!(tag[i]&4)) base.a[1][0]++,base.a[1][2]++;
            if(!(tag[i]&2)) base.a[2][0]++,base.a[2][2]++;
            if(!(tag[i]&1)) base.a[0][0]++;
            if(sum==0) base.a[0][2]++,base.a[2][1]++,base.a[2][3]+=2;
            if(sum==1) base.a[2][3]++;
            base=ksm(base,p[ii+1]-i);
            for(int x=0;x<4;x++) for(int y=0;y<4;y++) f[x]=(f[x]+dp[y]*base.a[x][y])%mod;
        }
        dp[0]=f[0],dp[1]=f[1],dp[2]=f[2],dp[3]=f[3];
    }
    cout<<(fac(n-cnt)-dp[0]+mod)%mod<<"\n";
}
int main(){
    freopen("perm.in","r",stdin);
    freopen("perm.out","w",stdout);
    ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    int Ca;cin>>Ca;while(Ca--)solve();
    return 0;
}